import { CART_ADD_ITEM, CART_REMOVE_ITEM, CART_SAVE_PAYMENT_METHOD, CART_SET_PAYMENT_RESULT, } from '../constants/cartConstants'

export const cartReducer = (state = { cartItems: [] }, action) => {
    switch (action.type) {
        case CART_ADD_ITEM:
            // payload is item
            const item = action.payload
            // Check if item already exists in cart
            const existItem = state.cartItems.find(x => x.product === item.product)

            if (existItem) {
                return {
                    ...state, /* state returns original version, but everything after is added or amends. */
                    cartItems: state.cartItems.map(x => x.product === existItem.product ? item : x)
                }
            } else {
                return {
                    ...state,
                    cartItems: [...state.cartItems, item]
                }
            }

        
        case CART_REMOVE_ITEM:
            return {
                ...state,
                /* filster will just keep every product that doesn't match the id (action.payload) */
                cartItems: state.cartItems.filter(x => x.product !== action.payload)
            } 

        case CART_SAVE_PAYMENT_METHOD:
            return {
               ...state,
               paymentMethod: action.payload,
           }

        case CART_SET_PAYMENT_RESULT:
            return {
                ...state,
                paymentResult: action.payload,
            }

        default:
            return state
    }
}